function folderForm(x,parent=''){let ww=w(state.world);let blocked=x?descendants(ww,x.id):new Set();let choices=[['','最上層'],...folderOptions(ww).filter(([id])=>id&&!blocked.has(id))];modal(x?'編輯資料夾':'新增資料夾',inputField('分類名稱','name',x?.name||'')+selectField('上層資料夾','parentId',choices,x?.parentId??parent),o=>{o.name=o.name.trim();if(!o.name){toast('請填寫分類名稱');return false}if(x)Object.assign(x,o);else ww.folders.push({id:uid(),...o});ww.categories=ww.folders.filter(f=>!f.parentId).map(f=>f.name);return true})}
function templateForm(x){modal(x?'編輯欄位範本':'新增欄位範本',inputField('欄位名稱','label',x?.label||'')+selectField('欄位類型','type',[['text','單行文字'],['textarea','長篇文字']],x?.type||'text'),o=>{if(!o.label.trim()){toast('請填寫欄位名稱');return false}if(x)Object.assign(x,o);else w(state.world).templates.push({id:uid(),...o});return true})}
function customForm(x){modal(x?'編輯自訂欄位':'新增自訂欄位',inputField('欄位名稱','label',x?.label||'')+inputField('內容','value',x?.value||'','textarea')+selectField('確認狀態','status',Object.entries(statuses),x?.status||'confirmed')+selectField('來源','origin',Object.entries(sources),x?.origin||'author'),o=>{if(!o.label.trim()){toast('請填寫欄位名稱');return false}if(x)Object.assign(x,o);else v().custom.push({id:uid(),...o});return true})}
function noteForm(x){modal('編輯暫存紀錄',inputField('內容','text',x.text,'textarea')+selectField('指定對象','target',[['none','未分類'],...db.worlds.map(ww=>['world:'+ww.id,'世界觀｜'+ww.name]),...db.characters.flatMap(ch=>ch.versions.map(ver=>['character:'+ch.id+':'+ver.id,'角色｜'+ch.name+'／'+ver.name]))],noteTarget(x))+selectField('狀態','status',Object.entries(statuses),x.status)+selectField('來源','origin',Object.entries(sources),x.origin),o=>{if(!o.text.trim())return false;Object.assign(x,{text:o.text,status:o.status,origin:o.origin,...parseTarget(o.target)});return true})}

